'use strict';
// MIRROR BREAK v14 — RUIN FINISHER: a low-HP BODY-BROKEN boss can be executed by the ruin carried from the previous fight.
(()=>{
 if(window.__parryMirrorBreakV14Loaded)return;window.__parryMirrorBreakV14Loaded=true;
 const state=window.__mirrorBreakState,v13=window.__mirrorBreakV13State;if(!state||!v13)return;
 const ROUTES=['ASH GATE','CAGE BREACH','BROKEN SPINE','ALTAR RIFT'];
 const FINISH=['GATE SPLIT','CAGE CRUSH','SPINE CLEAVE','ALTAR SHATTER'];
 const COLORS=['#ffc475','#94ead8','#ddb9ff','#d3ecff'];
 const s={seen:v13.history?.length||0,finishers:0,last:null,activeT:0,activeStart:0,source:-1,bossRef:null,wave:null,suppressDefeat:false};window.__mirrorBreakV14State=s;
 const style=document.createElement('style');style.textContent=`
 #mbRuinFinisher{position:fixed;left:50%;top:39%;transform:translate(-50%,-50%) scale(.95);z-index:44;pointer-events:none;opacity:0;min-width:270px;padding:10px 22px;text-align:center;background:linear-gradient(90deg,transparent,#071019f0 15%,#071019f0 85%,transparent);border-left:1px solid #f1cf83a0;border-right:1px solid #f1cf83a0;text-shadow:0 3px 14px #000;transition:opacity .10s,transform .10s;white-space:nowrap}
 #mbRuinFinisher.show{opacity:1;transform:translate(-50%,-50%) scale(1)}#mbRuinFinisher small{display:block;color:#c9d8d3;font-size:8px;letter-spacing:4.5px}#mbRuinFinisher b{display:block;margin-top:3px;color:#ffe09a;font-size:19px;letter-spacing:6px;font-weight:650}#mbRuinFinisher em{display:block;margin-top:3px;color:#bdd0ca;font-size:7px;letter-spacing:2.2px;font-style:normal}
 #mbRuinFinisherFlash{position:fixed;inset:0;z-index:33;pointer-events:none;opacity:0;background:radial-gradient(circle at 50% 46%,rgba(255,225,160,.15),transparent 27%),radial-gradient(circle at 50% 50%,transparent 42%,rgba(3,8,14,.24));transition:opacity .12s}
 body.mb-ruin-finisher #mbRuinFinisherFlash{opacity:1}
 body.mb-ruin-finisher #mbMirrorLoadout,body.mb-ruin-finisher #mbBreakHud,body.mb-ruin-finisher #mbScarMemory,body.mb-ruin-finisher #pbBanner,body.mb-ruin-finisher #pbCineBars,body.mb-ruin-finisher #pbDanger,body.mb-ruin-finisher #pbMirror,body.mb-ruin-finisher #pbPhaseStrip,body.mb-ruin-finisher #mbMirrorShift,body.mb-ruin-finisher #cue,body.mb-ruin-finisher #toast{opacity:0!important;visibility:hidden!important;pointer-events:none!important}
 body.mb-ruin-finisher #controls{opacity:.72;transition:opacity .12s}
 @media(max-height:500px){#mbRuinFinisher{top:41%;min-width:240px;padding:7px 18px}#mbRuinFinisher b{font-size:17px}}
 `;document.head.appendChild(style);
 const hud=document.createElement('div');hud.id='mbRuinFinisher';hud.innerHTML='<small>RUIN FINISHER</small><b>RUIN BREAK</b><em></em>';document.body.appendChild(hud);
 const flash=document.createElement('div');flash.id='mbRuinFinisherFlash';document.body.appendChild(flash);
 const baseAnnounce=announce;announce=function(text,duration){if(s.suppressDefeat&&String(text||'').replace(/\s/g,'')==='討伐')return;return baseAnnounce(text,duration)};
 const named=(d,name,last=false)=>{const list=d?.nodes?.filter?.(n=>n.name===name)||[];return last?list[list.length-1]:list[0]};
 const maxHp=()=>Math.max(1,boss?.spec?.hp||boss?.hp||1);
 const threshold=source=>Math.max(18,Math.min(38,maxHp()*(.115+source*.012)));
 const routePoint=()=>named(boss,'chest')?.p||named(boss,'hip')?.p||boss?.pos||V(0,1,0);
 function routeForce(source){const side=source%2?1:-1;if(source===0)return V(side*26,7,-9);if(source===1)return V(side*19,10,-15);if(source===2)return V(side*31,13,-5);return V(0,9,-34)}
 function extraImpulse(source){if(!boss?.nodes?.length)return;const chest=named(boss,'chest'),head=named(boss,'head'),hip=named(boss,'hip'),feet=boss.nodes.filter(n=>n.name==='foot');if(source===0){if(chest)boss.impulse(chest.p,V(-18,5,-4));if(head)boss.impulse(head.p,V(9,7,-3))}else if(source===1){if(hip)boss.impulse(hip.p,V(13,11,-10));if(head)boss.impulse(head.p,V(-10,3,-15))}else if(source===2){if(chest)boss.impulse(chest.p,V(20,11,-3));if(hip)boss.impulse(hip.p,V(-17,6,-2));if(feet[0])boss.impulse(feet[0].p,V(-12,13,2))}else{if(chest)boss.impulse(chest.p,V(0,8,-24));if(head)boss.impulse(head.p,V(4,9,-18));if(hip)boss.impulse(hip.p,V(-4,4,-16))}}
 function prepareWave(source,now){const meshes=v13.scene?.__mbDestructionRoute?.meshes||[];if(!meshes.length){s.wave=null;return}const count=Math.min(meshes.length,source===3?10:7),chosen=meshes.slice(Math.max(0,meshes.length-count));s.wave={source,start:now,items:chosen.map((m,i)=>({m,i,px:m.position.x,py:m.position.y,pz:m.position.z,rx:m.rotation.x,ry:m.rotation.y,rz:m.rotation.z}))}}
 function animateWave(now=performance.now()){const w=s.wave;if(!w)return;const t=Math.max(0,Math.min(1,(now-w.start)/880)),e=1-Math.pow(1-t,3),side=w.source%2?1:-1;for(const it of w.items){const m=it.m;if(!m?.parent)continue;const seed=(it.i+2)*(w.source+3),fan=((seed%5)-2)*.18;m.position.x=it.px+(fan+side*.18)*e;m.position.y=it.py-Math.min(it.py+.16,(.30+.09*(seed%4))*e);m.position.z=it.pz+(.28+.08*(seed%6))*e;m.rotation.x=it.rx+(.38+.12*(seed%4))*e;m.rotation.y=it.ry+fan*.55*e;m.rotation.z=it.rz+side*(.68+.14*(seed%5))*e}if(t>=1)s.wave=null}
 function clearCompetingPresentation(){for(const id of ['pbBanner','pbCineBars','pbDanger','pbMirror','mbMirrorShift'])document.getElementById(id)?.classList.remove('show');const toast=$('toast'),cue=$('cue');if(toast)toast.textContent='';if(cue)cue.textContent='';try{toastT=0}catch(_){}}
 function show(source,event,forcedKill){s.activeStart=performance.now();s.activeT=1.28;s.source=source;clearCompetingPresentation();document.body.classList.add('mb-ruin-finisher');hud.querySelector('small').textContent='RUIN FINISHER';hud.querySelector('b').textContent=FINISH[source];hud.querySelector('em').textContent=`${ROUTES[source]} · ${forcedKill?'EXECUTION':'CHAIN KO'}`;hud.classList.add('show');const p=routePoint();groundImpact(V(p.x,.06,p.z),2.25+source*.38);ring(V(p.x,.08,p.z),COLORS[source]);ring(V(p.x,.08,p.z),'#fff0b2');burst(V(p.x,.20,p.z),COLORS[source],24+source*6,6.0+source*.75);shake=Math.max(shake,.30+source*.035);hitstop=Math.max(hitstop,.075+source*.012);sound(210+source*70,.18,'triangle',.028);prepareWave(source,performance.now());s.finishers++;s.last={serial:s.finishers,source,route:ROUTES[source],name:FINISH[source],level,eventSerial:event.serial,forcedKill,at:performance.now()}}
 function execute(event){const source=event.source;if(source<0||source>3||boss!==s.bossRef&&s.bossRef){s.bossRef=boss}if(!boss||!player||player.hp<=0||mode!=='play'||event.level!==level||!state.broken||state.boss!==boss)return;const limit=threshold(source);if(boss.hp>limit)return;const alreadyDead=boss.hp<=0,p=routePoint();if(!alreadyDead){const inv=boss.invuln;boss.invuln=0;s.suppressDefeat=true;try{hurt(boss,boss.hp+2,routeForce(source),p)}finally{s.suppressDefeat=false;boss.invuln=Math.max(boss.invuln,inv,.12);v13.launch=null}}extraImpulse(source);show(source,event,!alreadyDead)}
 function syncChains(){const h=v13.history||[];while(s.seen<h.length){const event=h[s.seen++];if(event)execute(event)}}
 function frame(now){syncChains();animateWave(now);if(s.activeT>0){s.activeT=Math.max(0,1.28-(now-s.activeStart)/1000);if(s.activeT<=0){hud.classList.remove('show');document.body.classList.remove('mb-ruin-finisher')}}requestAnimationFrame(frame)}requestAnimationFrame(frame);
 const baseReset=reset;reset=function(l=0){const prev=typeof level==='number'?level:-1,out=baseReset(l);s.seen=v13.history?.length||0;s.activeT=0;s.activeStart=0;s.source=-1;s.bossRef=boss;s.wave=null;s.suppressDefeat=false;hud.classList.remove('show');document.body.classList.remove('mb-ruin-finisher');if(l===0&&prev>=4){s.finishers=0;s.last=null}return out};
 const priorDiag=window.parryMirrorBreakDiagnostics;window.parryMirrorBreakDiagnostics=()=>{const d=priorDiag?priorDiag():{};return{...d,v14:true,ruinFinisher:true,ruinFinishers:s.finishers,ruinFinisherActive:s.activeT>0,ruinFinisherLast:s.last?{...s.last}:null,ruinFinisherThreshold:+threshold(Math.max(0,s.source)).toFixed(1),ruinFinisherWave:!!s.wave,ruinFinisherExclusive:document.body.classList.contains('mb-ruin-finisher')}};
 window.parryRuinFinisherDiagnostics=()=>({v14:true,finishers:s.finishers,active:s.activeT>0,last:s.last?{...s.last}:null,wave:!!s.wave,seen:s.seen,exclusive:document.body.classList.contains('mb-ruin-finisher')});
 s.bossRef=boss;
})();

// V15 loads only after v14 has installed its execution state and presentation wrappers.
(()=>{if(window.__parryMirrorBreakV15Queued)return;window.__parryMirrorBreakV15Queued=true;const src=document.currentScript?.src||'',q=src.includes('?')?'?'+src.split('?').slice(1).join('?'):'',v15=document.createElement('script');v15.src='./mirror-break-v15-ruin-target.js'+q;document.body.appendChild(v15)})();
